name: PR Size Labeler

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  label-pr:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Get changed files
        id: changed-files
        uses: tj-actions/changed-files@v45.0.6
        with:
          use_rest_api: true

      - name: Calculate PR size
        id: pr-size
        run: |
          total_changes=0
          for file in ${{ steps.changed-files.outputs.all_changed_files }}; do
            if [[ -f "$file" ]]; then
              # Count lines added and removed for each file
              changes=$(git diff --no-index /dev/null "$file" 2>/dev/null | grep -c "^+" || git diff HEAD~1 "$file" 2>/dev/null | grep -c "^+" || echo 0)
              total_changes=$((total_changes + changes))
            fi
          done
          echo "total_changes=$total_changes" >> $GITHUB_OUTPUT

      - name: Apply size labels
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { total_changes } = process.env;
            const prNumber = context.payload.pull_request.number;

            // Remove existing size labels
            const labels = await github.rest.issues.listLabelsOnIssue({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });

            const sizeLabels = labels.data.filter(label => label.name.startsWith('size/'));
            for (const label of sizeLabels) {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                name: label.name
              });
            }

            // Apply new size label based on changes
            let sizeLabel = '';
            if (total_changes < 50) {
              sizeLabel = 'size/XS';
            } else if (total_changes < 100) {
              sizeLabel = 'size/S';
            } else if (total_changes < 500) {
              sizeLabel = 'size/M';
            } else if (total_changes < 1000) {
              sizeLabel = 'size/L';
            } else {
              sizeLabel = 'size/XL';
            }

            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              labels: [sizeLabel]
            });
